# -*- coding: utf-8 -*-
"""
Exceptions used in taf.ul.sc.perf package
"""
import logging
import traceback
import sys


class ProcedureException(Exception):
    pass


class ProcedureStepError(ProcedureException):
    def __init__(self, exc, step):
        msg = "Require step [{}] FAILED because of {}".format(step, repr(exc))
        logging.error(msg="{}\n{}Running teardown".format(msg, ' ' * 10))

        exc_type, exc_value, exc_tb = sys.exc_info()
        exc_traceback = traceback.format_exception(exc_type, exc_value, exc_tb)
        msg_err = ' '.join(exc_traceback)

        super(ProcedureStepError, self).__init__("{}\n{}".format(msg, msg_err))


class FileNotFoundError(ProcedureException):
    pass


class BTSNotOnAir(ProcedureException):
    pass


class UENotConnected(ProcedureException):
    pass
